param([string]$InstallDir = 'C:\TailscaleAdmin', [string]$Domain = 'tailscale-admin.local', [int]$Port = 8787, [string]$LanAddress = '') # Configure the destination, private domain and LAN port.
$ErrorActionPreference = 'Stop' # Stop on any partial installation error.
$identity = [Security.Principal.WindowsIdentity]::GetCurrent() # Determine the account running the installer.
if (-not ([Security.Principal.WindowsPrincipal]::new($identity)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'Run install.cmd as administrator.' } # Require rights for the startup task and restricted firewall rule.
if ($Port -lt 1 -or $Port -gt 65535 -or $Domain -notmatch '^(?=.{1,253}$)[a-zA-Z0-9]+(?:[.-][a-zA-Z0-9]+)*$') { throw 'Invalid domain or port.' } # Reject invalid address settings before changing files.
$sourceRoot = Split-Path $PSScriptRoot -Parent # Locate the fully extracted release directory.
$InstallDir = [IO.Path]::GetFullPath($InstallDir).TrimEnd('\') # Resolve the destination once for all following operations.
if ($InstallDir -eq [IO.Path]::GetPathRoot($InstallDir).TrimEnd('\')) { throw 'The installation directory cannot be a drive root.' } # Keep installation files in a dedicated directory.
$nodeCommand = Get-Command node.exe -ErrorAction SilentlyContinue # Use the operator's installed Node.js runtime instead of shipping a platform binary.
if (-not $nodeCommand) { throw 'Install Node.js 18 or newer and make sure node.exe is on PATH.' } # Explain the missing prerequisite before making changes.
$nodeSource = $nodeCommand.Source # Resolve the exact executable path used by the scheduled task.
if (-not (Test-Path -LiteralPath $nodeSource)) { throw 'The Node.js executable on PATH could not be found.' } # Explain an invalid PATH entry before making changes.
$ipCandidates = @(Get-NetIPConfiguration | Where-Object { $_.IPv4DefaultGateway -and $_.NetAdapter.Status -eq 'Up' } | ForEach-Object { $_.IPv4Address.IPAddress } | Where-Object { $_ -notmatch '^(127\.|169\.254\.|100\.)' }) # Prefer actual gateway-connected LAN adapters over Tailscale or APIPA.
if (-not $LanAddress) { if ($ipCandidates.Count -eq 1) { $LanAddress = $ipCandidates[0] } else { Write-Host ('Available LAN addresses: ' + ($ipCandidates -join ', ')); $LanAddress = Read-Host 'Enter the IPv4 address on the LAN used by clients' } } # Request an explicit address when multiple physical networks are possible.
$parsed = $null # Prepare a typed address for validation.
if (-not [Net.IPAddress]::TryParse($LanAddress, [ref]$parsed) -or $parsed.AddressFamily -ne [Net.Sockets.AddressFamily]::InterNetwork -or $LanAddress -notin @(Get-NetIPAddress -AddressFamily IPv4 | Select-Object -ExpandProperty IPAddress)) { throw 'LAN address must be an IPv4 address assigned to this computer.' } # Never advertise a guessed or remote LAN address.
$existing = @(Get-NetTCPConnection -State Listen -LocalPort $Port -ErrorAction SilentlyContinue) # Detect a conflicting web service before installation.
$ourProcesses = @(Get-CimInstance Win32_Process -Filter "Name='node.exe'" | Where-Object { $_.ExecutablePath -eq $nodeSource -and $_.CommandLine.Contains((Join-Path $InstallDir 'deployment-launcher.mjs')) }) # Identify only processes belonging to this exact installation.
if (@($existing | Where-Object { $_.OwningProcess -notin $ourProcesses.ProcessId }).Count) { throw "Port $Port is used by another service. Choose another port or free it manually." } # Preserve unrelated web servers and their ports.
$newPassword = $null # Keep a password only when the installation needs a new one.
if (-not (Test-Path -LiteralPath (Join-Path $InstallDir 'data\access.json'))) { $newPassword = Read-Host 'Set the admin password (12-256 characters)' -AsSecureString; $confirmation = Read-Host 'Repeat the admin password' -AsSecureString; if ([Net.NetworkCredential]::new('', $newPassword).Password -cne [Net.NetworkCredential]::new('', $confirmation).Password) { throw 'Passwords do not match.' }; if ($newPassword.Length -lt 12 -or $newPassword.Length -gt 256) { throw 'Password length must be 12-256 characters.' } } # Obtain and validate a new login without displaying it.
$migrationCode = $null # Keep encrypted migration optional for clean installations.
if ((Test-Path -LiteralPath (Join-Path $sourceRoot 'migration.enc.json')) -and -not (Test-Path -LiteralPath (Join-Path $InstallDir 'data\config.json'))) { $migrationCode = Read-Host 'Enter the separate migration code, or press Enter to configure OAuth later' -AsSecureString } # Ask for a code only when an encrypted migration is present and no live config exists.
if (Get-ScheduledTask -TaskName 'TailscaleAdmin-LAN' -ErrorAction SilentlyContinue) { Stop-ScheduledTask -TaskName 'TailscaleAdmin-LAN' } # Stop only the existing task with this deployment identity.
foreach ($process in $ourProcesses) { Stop-Process -Id $process.ProcessId -ErrorAction Stop } # Stop only verified processes before updating their files.
New-Item -ItemType Directory -Path $InstallDir -Force | Out-Null # Create the dedicated installation directory.
$files = @('server.mjs','enrollment-manager.mjs','access-control.mjs','credential-manager.mjs','oauth-manager.mjs','remote-manager.mjs','remote-operations.mjs','fleet-manager.mjs','fleet-scripts.mjs','node-monitor.mjs','relay-status.mjs','runtime-discovery.mjs','deployment-tools.mjs','deployment-launcher.mjs','launcher.mjs','run-console.cmd','package.json','README.md') # Copy only executable sources and documentation, never the development data tree.
if ($sourceRoot.TrimEnd('\') -ne $InstallDir) { foreach ($name in $files) { Copy-Item -LiteralPath (Join-Path $sourceRoot $name) -Destination (Join-Path $InstallDir $name) -Force }; foreach ($name in @('public','deploy')) { New-Item -ItemType Directory -Path (Join-Path $InstallDir $name) -Force | Out-Null; Copy-Item -Path (Join-Path $sourceRoot ($name + '\*')) -Destination (Join-Path $InstallDir $name) -Recurse -Force } } # Preserve existing data while replacing only allowlisted application files.
$dataDir = Join-Path $InstallDir 'data' # Keep operational state outside the replaceable source files.
New-Item -ItemType Directory -Path $dataDir -Force | Out-Null # Prepare the private configuration directory.
$accountSid = '*' + $identity.User.Value # Refer to the installing user by SID for all Windows display languages.
& icacls.exe $InstallDir '/inheritance:r' '/grant:r' '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' "${accountSid}:(OI)(CI)F" | Out-Null # Restrict runtime modification and configuration access to SYSTEM, administrators and the installer account.
if ($LASTEXITCODE -ne 0) { throw 'Cannot restrict installation directory permissions.' } # Do not continue with an insecure writable service directory.
& icacls.exe $dataDir '/inheritance:r' '/grant:r' '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' "${accountSid}:(OI)(CI)F" | Out-Null # Restrict the credential directory even on upgrades of an existing installation.
if ($LASTEXITCODE -ne 0) { throw 'Cannot restrict credential directory permissions.' } # Refuse to publish the service if credentials cannot be protected.
$node = $nodeSource # Pin the installed executable used by setup and the scheduled task.
if ($newPassword) { try { $env:TSADMIN_SETUP_PASSWORD = [Net.NetworkCredential]::new('', $newPassword).Password; & $node (Join-Path $InstallDir 'deployment-tools.mjs') password; if ($LASTEXITCODE -ne 0) { throw 'Cannot initialize administrator password.' } } finally { Remove-Item Env:\TSADMIN_SETUP_PASSWORD -ErrorAction SilentlyContinue } } # Pass the chosen password only to a short-lived local child process.
if ($migrationCode -and $migrationCode.Length) { Copy-Item -LiteralPath (Join-Path $sourceRoot 'migration.enc.json') -Destination (Join-Path $InstallDir 'migration.enc.json') -Force; try { $env:TSADMIN_MIGRATION_CODE = [Net.NetworkCredential]::new('', $migrationCode).Password; & $node (Join-Path $InstallDir 'deployment-tools.mjs') migrate; if ($LASTEXITCODE -ne 0) { throw 'Migration failed; no previous configuration was overwritten.' } } finally { Remove-Item Env:\TSADMIN_MIGRATION_CODE -ErrorAction SilentlyContinue } } # Restore only authenticated ciphertext while preserving any pre-existing configuration.
$allowedHosts = @($Domain, $env:COMPUTERNAME, $LanAddress) # Permit the chosen domain and actual host identities.
$tailBin = Join-Path $env:ProgramFiles 'Tailscale\tailscale.exe' # Discover the installed Tailscale client without changing its settings.
if (Test-Path -LiteralPath $tailBin) { try { $tail = (& $tailBin status --json | ConvertFrom-Json); $allowedHosts += $tail.TailscaleIPs; if ($tail.Self.DNSName) { $allowedHosts += $tail.Self.DNSName.TrimEnd('.') } } catch { Write-Warning 'Tailscale status was unavailable; LAN deployment will continue.' } } # Include verified Tailscale addresses and the MagicDNS hostname when available.
$settings = @{ port = $Port; domain = $Domain; lanAddress = $LanAddress; allowedHosts = @($allowedHosts | Where-Object { $_ } | Select-Object -Unique) } # Record only address settings, never passwords or OAuth secrets.
[IO.File]::WriteAllText((Join-Path $dataDir 'deployment.json'), ($settings | ConvertTo-Json -Depth 5), [Text.UTF8Encoding]::new($false)) # Save a UTF-8 configuration readable by the bundled Node runtime.
& (Join-Path $InstallDir 'deploy\set-domain.ps1') -Address $LanAddress -Domain $Domain # Configure the private domain on the server itself while retaining other hosts mappings.
$rule = Get-NetFirewallRule -Name 'TailscaleAdmin-LAN' -ErrorAction SilentlyContinue # Locate only the firewall rule owned by this deployment.
if ($rule) { $rule | Remove-NetFirewallRule } # Replace this application's old rule while preserving every unrelated rule.
New-NetFirewallRule -Name 'TailscaleAdmin-LAN' -DisplayName 'Tailscale Admin LAN' -Direction Inbound -Action Allow -Protocol TCP -LocalPort $Port -Program $node -RemoteAddress 'LocalSubnet','100.64.0.0/10','fd7a:115c:a1e0::/48' -Profile Any | Out-Null # Limit inbound access to local subnets and Tailscale peers rather than the public Internet.
$action = New-ScheduledTaskAction -Execute $node -Argument ('"' + (Join-Path $InstallDir 'deployment-launcher.mjs') + '"') -WorkingDirectory $InstallDir # Launch the service with an explicit runtime, script and working directory.
$trigger = New-ScheduledTaskTrigger -AtStartup # Start independently of desktop login after reboot.
$principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest # Run without storing a Windows account password.
$taskSettings = New-ScheduledTaskSettingsSet -StartWhenAvailable -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -ExecutionTimeLimit ([TimeSpan]::Zero) -MultipleInstances IgnoreNew -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries # Restart unexpected exits while keeping only one persistent instance.
Register-ScheduledTask -TaskName 'TailscaleAdmin-LAN' -Action $action -Trigger $trigger -Principal $principal -Settings $taskSettings -Force | Out-Null # Register or replace only this application's startup task.
Start-ScheduledTask -TaskName 'TailscaleAdmin-LAN' # Start the configured service immediately.
$ready = $false # Require a healthy live listener before reporting success.
for ($attempt = 0; $attempt -lt 25; $attempt++) { try { $health = Invoke-RestMethod -Uri ('http://127.0.0.1:' + $Port + '/api/health') -TimeoutSec 2; if ($health.ok -and $health.mock -eq $false) { $ready = $true; break } } catch { }; Start-Sleep -Milliseconds 400 } # Wait briefly for actual application startup instead of assuming task registration succeeded.
if (-not $ready) { throw 'Startup failed. Inspect the TailscaleAdmin-LAN scheduled task before using the service.' } # Leave a truthful failure when the application is not reachable.
$suffix = if ($Port -eq 80) { '' } else { ':' + $Port } # Omit the port only for standard HTTP.
$addresses = @(('Domain: http://' + $Domain + $suffix), ('LAN: http://' + $LanAddress + $suffix), 'Login user: admin', 'Password: the password chosen during installation', 'Client setup: run deploy\set-domain.ps1 with the LAN address above on each LAN PC, or configure the router DNS.') # Provide usable URLs without saving the chosen password.
$addresses | Set-Content -LiteralPath (Join-Path $InstallDir 'ACCESS-URLS.txt') -Encoding UTF8 # Keep the target's actual LAN address available for other clients.
Write-Host ($addresses -join [Environment]::NewLine) # Report only verified installation URLs and local login guidance.
